async fn case(index: usize) -> Result<()> {
    let fixture = TestDatabase::memory()?;
    fixture.stores.transaction(move |tx| {
  let cases:Vec<Value>=serde_json::from_str(ORACLE)?;let input=&cases[index]["input"];
  let projection:OrchestrationV2ThreadProjection=serde_json::from_value(input["projection"].clone())?;
  let command_id:CommandId=serde_json::from_value(input["command"]["commandId"].clone())?;
  let thread_id=serde_json::from_value(input["command"]["threadId"].clone())?;
  let attachments:Vec<String>=serde_json::from_value(input["attachmentIds"].clone())?;
  let now:IsoDateTime=serde_json::from_value(input["now"].clone())?;
  let plan=plan_thread_deletion(&command_id,&thread_id,&projection,&attachments,&now,&Ids(AtomicU64::new(0)))?;
  assert_eq!(serde_json::to_value(&plan.events)?,cases[index]["result"]["events"]);
  let actual:Vec<_>=plan.effects.iter().map(|effect|json!({"id":effect.id,"commandId":effect.command_id,"threadId":effect.thread_id,"request":effect.request})).collect();
  assert_eq!(json!(actual),cases[index]["result"]["effects"]);
  let store=EventStore::new();store.append(tx,Some(&command_id),&plan.events)?;
  outbox::enqueue(tx,&plan.effects,&now.0)?;
  let events=store.read(tx,&EventFilter::default())?;
  assert_eq!(events.len(),plan.events.len());
  for (event,expected) in events.iter().zip(&plan.events) {assert_eq!(serde_json::to_value(event)?["event"],serde_json::to_value(expected)?);}
  assert_eq!(projection,serde_json::from_value(input["projection"].clone())?);
  Ok(())
 }).await
}
