#[tokio::test]
async fn cleanup_routes_effects_and_propagates_backend_failure() -> Result<()> {
    use async_trait::async_trait;
    use std::sync::Arc;
    use t3_orchestration::{
        api::{ResourceCleanup, ResourceKind},
        effects::EffectRequest,
        error::Error,
        ports::thread_project::resource_cleanup_service::ResourceCleanupService,
    };
    use tokio::sync::mpsc;
    struct Cleanup(mpsc::UnboundedSender<ResourceKind>);
    #[async_trait]
    impl ResourceCleanup for Cleanup {
        async fn cleanup(&self, thread_id: ThreadId, kind: ResourceKind) -> Result<()> {
            assert_eq!(thread_id.0, "thread");
            if matches!(kind, ResourceKind::Devices) {
                return Err(Error::Service {
                    operation: "fixture",
                    detail: "device close failed".into(),
                });
            }
            self.0.send(kind).expect("receiver");
            Ok(())
        }
    }
    let (sender, mut calls) = mpsc::unbounded_channel();
    let service = ResourceCleanupService::new(Arc::new(Cleanup(sender)));
    let requests = [
        EffectRequest::CleanupScheduledTasks,
        EffectRequest::CleanupTerminals,
        EffectRequest::CleanupPreviews,
        EffectRequest::CleanupAttachments {
            attachment_ids: vec!["one".into(), "two".into()],
        },
    ];
    for request in &requests {
        service.execute(ThreadId("thread".into()), request).await?;
    }
    assert!(matches!(
        calls.recv().await,
        Some(ResourceKind::ScheduledTasks)
    ));
    assert!(matches!(calls.recv().await, Some(ResourceKind::Terminals)));
    assert!(matches!(calls.recv().await, Some(ResourceKind::Previews)));
    assert!(
        matches!(calls.recv().await,Some(ResourceKind::Attachments(ids)) if ids==["one","two"])
    );
    assert!(matches!(
        service.cleanup_devices(ThreadId("thread".into())).await,
        Err(Error::Service {
            operation: "device",
            ..
        })
    ));
    assert!(matches!(
        service
            .execute(
                ThreadId("thread".into()),
                &EffectRequest::StopDelegated { reason: None }
            )
            .await,
        Err(Error::Unsupported(_))
    ));
    Ok(())
}
